namespace Verso.Domain.Documents;

public enum DocumentStatus
{
    /// <summary>Printed and stored in the staging area.</summary>
    Generated,

    /// <summary>Copied to its archive location, hash re-verified, archive record written.</summary>
    Archived,
}

/// <summary>
/// A PDF produced by an execution's generate-pdf step. At most one per (execution, node, iteration): a re-run of the step
/// reuses it instead of creating a duplicate; a step inside a For each loop makes one per item. Storage keys are generated by Verso, never taken from input.
/// </summary>
public sealed class Document
{
    public const string PdfContentType = "application/pdf";

    private Document() { } // EF Core

    public Guid Id { get; private set; }
    public Guid ExecutionId { get; private set; }
    public string NodeId { get; private set; } = "";

    /// <summary>0 outside a For each loop; inside one, the 1-based item the document was made for.</summary>
    public int Iteration { get; private set; }

    public Guid TemplateVersionId { get; private set; }

    /// <summary>From the node's filename pattern, sanitized.</summary>
    public string FileName { get; private set; } = "";

    public string ContentType { get; private set; } = PdfContentType;
    public long SizeBytes { get; private set; }

    /// <summary>SHA-256 (hex) of the content; re-verified when archived.</summary>
    public string Sha256 { get; private set; } = "";

    public string StorageProvider { get; private set; } = "";
    public string StorageKey { get; private set; } = "";
    public DocumentStatus Status { get; private set; }
    public DateTimeOffset CreatedAt { get; private set; }
    public DateTimeOffset? ArchivedAt { get; private set; }

    public static Document Generate(
        Guid executionId, string nodeId, Guid templateVersionId, string fileName, long sizeBytes, string sha256,
        string storageProvider, string storageKey, DateTimeOffset now, Guid? id = null, int iteration = 0) => new()
    {
        Id = id ?? Guid.CreateVersion7(now),
        ExecutionId = executionId,
        NodeId = nodeId,
        Iteration = iteration,
        TemplateVersionId = templateVersionId,
        FileName = fileName,
        SizeBytes = sizeBytes,
        Sha256 = sha256,
        StorageProvider = storageProvider,
        StorageKey = storageKey,
        Status = DocumentStatus.Generated,
        CreatedAt = now,
    };

    public void MarkArchived(string archiveStorageKey, DateTimeOffset now)
    {
        if (Status == DocumentStatus.Archived)
        {
            throw new DomainRuleException("document.already_archived", $"Document {Id} is already archived.");
        }

        StorageKey = archiveStorageKey;
        Status = DocumentStatus.Archived;
        ArchivedAt = now;
    }
}

/// <summary>Write-once archive entry for a document: where it is filed, its metadata and how long it is kept.</summary>
public sealed class ArchiveRecord
{
    private ArchiveRecord() { } // EF Core

    public Guid Id { get; private set; }
    public Guid DocumentId { get; private set; }
    public DateTimeOffset ArchivedAt { get; private set; }

    /// <summary><c>7y</c>, <c>10y</c> or <c>permanent</c>, as configured on the archive node.</summary>
    public string Retention { get; private set; } = "";

    /// <summary>Null when kept permanently. At expiry nothing is deleted in the MVP; the date is recorded only.</summary>
    public DateTimeOffset? RetentionUntil { get; private set; }

    /// <summary>The node's folder pattern resolved and sanitized (archive metadata, not a file-system path).</summary>
    public string FolderPath { get; private set; } = "";

    /// <summary>JSON object of key → value from the node's metadata settings.</summary>
    public string Metadata { get; private set; } = "{}";

    /// <summary>File name and metadata values, one per line: what archive search matches against (keys are not searched).</summary>
    public string SearchText { get; private set; } = "";

    public static ArchiveRecord Create(
        Guid documentId, string retention, DateTimeOffset? retentionUntil, string folderPath, string metadataJson, string searchText, DateTimeOffset now) => new()
    {
        Id = Guid.CreateVersion7(now),
        DocumentId = documentId,
        ArchivedAt = now,
        Retention = retention,
        RetentionUntil = retentionUntil,
        FolderPath = folderPath,
        Metadata = metadataJson,
        SearchText = searchText,
    };
}
